// The simplest possible vertex shader (GLSL)
// This shader passes vertex positions straight through unchanged
#version 330 core

layout(location = 0) in vec3 aPos;  // Vertex attribute: position

void main()
{
    gl_Position = vec4(aPos, 1.0);  // Output clip-space position
}

// The simplest possible fragment shader (GLSL)
// This shader colors every pixel solid red
#version 330 core

out vec4 FragColor;  // Output color to the framebuffer

void main()
{
    FragColor = vec4(1.0, 0.0, 0.0, 1.0);  // RGBA: Red, Green, Blue, Alpha
}

