// Texture sampling in the fragment shader
#version 330 core

in vec2 texCoord;
in vec3 worldPos;

uniform sampler2D diffuseMap;     // Base color texture
uniform sampler2D normalMap;      // Normal map for surface detail
uniform sampler2D specularMap;    // Specular intensity

out vec4 FragColor;

void main()
{
    // Sample diffuse color with default mipmapping
    vec3 diffuse = texture(diffuseMap, texCoord).rgb;

    // Sample normal map and transform from [0,1] to [-1,1]
    vec3 normal = texture(normalMap, texCoord).rgb;
    normal = normalize(normal * 2.0 - 1.0);

    // Sample specular intensity
    float specular = texture(specularMap, texCoord).r;

    // Combine for final color
    FragColor = vec4(diffuse * (0.5 + specular * 0.5), 1.0);
}

// Advanced texture sampling techniques
#version 330 core

in vec2 texCoord;

uniform sampler2D mainTexture;
uniform float time;

out vec4 FragColor;

void main()
{
    // Animated UV distortion for water/ripple effect
    vec2 distortedUV = texCoord;
    distortedUV.x += sin(distortedUV.y * 10.0 + time) * 0.01;
    distortedUV.y += cos(distortedUV.x * 10.0 + time) * 0.01;

    // Sample with distorted coordinates
    vec4 color = texture(mainTexture, distortedUV);

    // Manual bilinear filtering approximation for pixel art
    vec2 texSize = vec2(textureSize(mainTexture, 0));
    vec2 pixelUV = texCoord * texSize;
    vec2 frac = fract(pixelUV);

    // Sharp pixel art look using step function
    vec2 sharpUV = (floor(pixelUV) + step(0.5, frac)) / texSize;
    vec4 pixelArt = texture(mainTexture, sharpUV);

    // Mix between smooth and pixelated based on distance
    float dist = length(texCoord - 0.5);
    FragColor = mix(color, pixelArt, smoothstep(0.3, 0.6, dist));
}

// Lambertian diffuse lighting (vertex shader)
#version 330 core

layout(location = 0) in vec3 aPos;
layout(location = 1) in vec3 aNormal;

uniform mat4 mvp;
uniform mat4 model;

out vec3 worldNormal;
out vec3 worldPos;

void main()
{
    worldPos = vec3(model * vec4(aPos, 1.0));
    worldNormal = mat3(transpose(inverse(model))) * aNormal;
    gl_Position = mvp * vec4(aPos, 1.0);
}

// Lambertian diffuse lighting (fragment shader)
#version 330 core

in vec3 worldNormal;
in vec3 worldPos;

uniform vec3 lightPos;
uniform vec3 lightColor;
uniform vec3 objectColor;

out vec4 FragColor;

void main()
{
    // Normalize the interpolated normal
    vec3 N = normalize(worldNormal);

    // Calculate light direction (from surface to light)
    vec3 L = normalize(lightPos - worldPos);

    // Lambertian diffuse: cosine of angle between normal and light
    float diff = max(dot(N, L), 0.0);

    // Combine light color, object color, and diffuse factor
    vec3 diffuse = diff * lightColor * objectColor;

    // Add small ambient term so unlit areas aren't pure black
    vec3 ambient = 0.1 * lightColor * objectColor;

    FragColor = vec4(ambient + diffuse, 1.0);
}

// Blinn-Phong lighting model
#version 330 core

in vec3 worldNormal;
in vec3 worldPos;

uniform vec3 lightPos;
uniform vec3 lightColor;
uniform vec3 objectColor;
uniform vec3 viewPos;      // Camera position in world space
uniform float shininess;   // Typically 32 to 256

out vec4 FragColor;

void main()
{
    vec3 N = normalize(worldNormal);
    vec3 L = normalize(lightPos - worldPos);
    vec3 V = normalize(viewPos - worldPos);

    // Diffuse (Lambertian)
    float diff = max(dot(N, L), 0.0);
    vec3 diffuse = diff * lightColor;

    // Specular (Blinn-Phong)
    vec3 H = normalize(L + V);  // Half-vector
    float spec = pow(max(dot(N, H), 0.0), shininess);
    vec3 specular = spec * lightColor;

    // Ambient
    vec3 ambient = 0.1 * lightColor;

    // Combine all components
    vec3 result = (ambient + diffuse + specular) * objectColor;
    FragColor = vec4(result, 1.0);
}

// Multiple light types in a single shader
#version 330 core

#define MAX_POINT_LIGHTS 4

struct PointLight {
    vec3 position;
    vec3 color;
    float constant;
    float linear;
    float quadratic;
};

struct SpotLight {
    vec3 position;
    vec3 direction;
    vec3 color;
    float cutOff;       // Cosine of inner angle
    float outerCutOff;  // Cosine of outer angle
};

in vec3 worldNormal;
in vec3 worldPos;

uniform vec3 viewPos;
uniform vec3 dirLightDir;
uniform vec3 dirLightColor;
uniform PointLight pointLights[MAX_POINT_LIGHTS];
uniform SpotLight spotLight;
uniform int numPointLights;

out vec4 FragColor;

vec3 CalcDirLight(vec3 normal, vec3 viewDir)
{
    vec3 lightDir = normalize(-dirLightDir);  // Direction TO the light
    float diff = max(dot(normal, lightDir), 0.0);
    vec3 reflectDir = reflect(-lightDir, normal);
    float spec = pow(max(dot(viewDir, reflectDir), 0.0), 32.0);

    return (0.1 + diff + spec) * dirLightColor;
}

vec3 CalcPointLight(PointLight light, vec3 normal, vec3 viewDir)
{
    vec3 lightDir = normalize(light.position - worldPos);
    float diff = max(dot(normal, lightDir), 0.0);
    vec3 reflectDir = reflect(-lightDir, normal);
    float spec = pow(max(dot(viewDir, reflectDir), 0.0), 32.0);

    // Attenuation
    float dist = length(light.position - worldPos);
    float attenuation = 1.0 / (light.constant + light.linear * dist 
                               + light.quadratic * dist * dist);

    return (0.1 + diff + spec) * light.color * attenuation;
}

vec3 CalcSpotLight(SpotLight light, vec3 normal, vec3 viewDir)
{
    vec3 lightDir = normalize(light.position - worldPos);
    float diff = max(dot(normal, lightDir), 0.0);

    // Spotlight cone calculation
    float theta = dot(lightDir, normalize(-light.direction));
    float epsilon = light.cutOff - light.outerCutOff;
    float intensity = clamp((theta - light.outerCutOff) / epsilon, 0.0, 1.0);

    return diff * light.color * intensity;
}

void main()
{
    vec3 N = normalize(worldNormal);
    vec3 V = normalize(viewPos - worldPos);

    vec3 result = CalcDirLight(N, V);

    for (int i = 0; i < numPointLights; i++) {
        result += CalcPointLight(pointLights[i], N, V);
    }

    result += CalcSpotLight(spotLight, N, V);

    FragColor = vec4(result, 1.0);
}

// Normal mapping with TBN matrix
#version 330 core

layout(location = 0) in vec3 aPos;
layout(location = 1) in vec3 aNormal;
layout(location = 2) in vec2 aTexCoord;
layout(location = 3) in vec3 aTangent;

uniform mat4 mvp;
uniform mat4 model;

out vec2 texCoord;
out vec3 worldPos;
out mat3 TBN;  // Tangent-to-world matrix

void main()
{
    worldPos = vec3(model * vec4(aPos, 1.0));
    texCoord = aTexCoord;

    // Build TBN matrix in world space
    vec3 N = normalize(mat3(model) * aNormal);
    vec3 T = normalize(mat3(model) * aTangent);
    // Re-orthogonalize T against N (Gram-Schmidt)
    T = normalize(T - dot(T, N) * N);
    vec3 B = cross(N, T);

    TBN = mat3(T, B, N);

    gl_Position = mvp * vec4(aPos, 1.0);
}

// Fragment shader using normal map
#version 330 core

in vec2 texCoord;
in vec3 worldPos;
in mat3 TBN;

uniform sampler2D diffuseMap;
uniform sampler2D normalMap;
uniform vec3 lightPos;
uniform vec3 viewPos;

out vec4 FragColor;

void main()
{
    // Sample and decode normal from texture
    vec3 normal = texture(normalMap, texCoord).rgb;
    normal = normal * 2.0 - 1.0;  // From [0,1] to [-1,1]

    // Transform normal from tangent space to world space
    vec3 N = normalize(TBN * normal);

    // Standard Blinn-Phong lighting
    vec3 L = normalize(lightPos - worldPos);
    vec3 V = normalize(viewPos - worldPos);
    vec3 H = normalize(L + V);

    float diff = max(dot(N, L), 0.0);
    float spec = pow(max(dot(N, H), 0.0), 64.0);

    vec3 diffuseColor = texture(diffuseMap, texCoord).rgb;
    vec3 ambient = 0.1 * diffuseColor;
    vec3 diffuse = diff * diffuseColor;
    vec3 specular = spec * vec3(0.5);

    FragColor = vec4(ambient + diffuse + specular, 1.0);
}

// Procedural water waves vertex shader
#version 330 core

layout(location = 0) in vec3 aPos;
layout(location = 1) in vec3 aNormal;
layout(location = 2) in vec2 aTexCoord;

uniform mat4 mvp;
uniform mat4 model;
uniform float time;

out vec3 worldPos;
out vec3 worldNormal;
out vec2 texCoord;

void main()
{
    vec3 pos = aPos;

    // Combine multiple sine waves for natural-looking water
    float wave1 = sin(pos.x * 2.0 + time * 1.5) * 0.3;
    float wave2 = sin(pos.z * 3.0 + time * 2.0) * 0.2;
    float wave3 = sin((pos.x + pos.z) * 1.5 + time * 0.5) * 0.15;

    pos.y += wave1 + wave2 + wave3;

    // Approximate new normal by sampling neighboring points
    float dx = 0.01;
    float wave1_dx = sin((pos.x + dx) * 2.0 + time * 1.5) * 0.3;
    float wave2_dx = sin(pos.z * 3.0 + time * 2.0) * 0.2;
    float h_dx = wave1_dx + wave2_dx + wave3;

    float wave1_dz = sin(pos.x * 2.0 + time * 1.5) * 0.3;
    float wave2_dz = sin((pos.z + dx) * 3.0 + time * 2.0) * 0.2;
    float h_dz = wave1_dz + wave2_dz + wave3;

    vec3 tangentX = vec3(dx, h_dx - pos.y, 0.0);
    vec3 tangentZ = vec3(0.0, h_dz - pos.y, dx);
    vec3 newNormal = normalize(cross(tangentZ, tangentX));

    worldPos = vec3(model * vec4(pos, 1.0));
    worldNormal = mat3(model) * newNormal;
    texCoord = aTexCoord;

    gl_Position = mvp * vec4(pos, 1.0);
}

// Vertex displacement from a height map texture
#version 330 core

layout(location = 0) in vec3 aPos;
layout(location = 1) in vec3 aNormal;
layout(location = 2) in vec2 aTexCoord;

uniform mat4 mvp;
uniform mat4 model;
uniform sampler2D heightMap;
uniform float displacementScale;

out vec2 texCoord;
out vec3 worldNormal;

void main()
{
    // Sample height from texture (use vertex UVs)
    float height = texture(heightMap, aTexCoord).r;

    // Displace along normal direction
    vec3 displacedPos = aPos + aNormal * height * displacementScale;

    worldNormal = mat3(transpose(inverse(model))) * aNormal;
    texCoord = aTexCoord;

    gl_Position = mvp * vec4(displacedPos, 1.0);
}

// Procedural patterns fragment shader
#version 330 core

in vec2 texCoord;
uniform float time;

out vec4 FragColor;

// 2D rotation matrix
mat2 rotate(float angle)
{
    float c = cos(angle), s = sin(angle);
    return mat2(c, -s, s, c);
}

void main()
{
    vec2 uv = texCoord;

    // Animated rotating grid
    uv = rotate(time * 0.5) * (uv - 0.5) + 0.5;

    // Checkerboard pattern
    vec2 grid = floor(uv * 8.0);
    float checker = mod(grid.x + grid.y, 2.0);

    // Circular rings
    float dist = length(uv - 0.5);
    float rings = sin(dist * 40.0 - time * 3.0) * 0.5 + 0.5;

    // Combine patterns
    vec3 color = mix(vec3(0.1, 0.2, 0.4), vec3(0.8, 0.9, 1.0), checker);
    color += vec3(0.2, 0.5, 0.8) * rings * 0.3;

    // Animated pulse at center
    float pulse = exp(-dist * 8.0) * (sin(time * 4.0) * 0.5 + 0.5);
    color += vec3(1.0, 0.8, 0.3) * pulse;

    FragColor = vec4(color, 1.0);
}

// Simple value noise and fBm implementation
#version 330 core

in vec2 texCoord;
uniform float time;

out vec4 FragColor;

// Pseudo-random hash function
float hash(vec2 p)
{
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

// 2D value noise
float noise(vec2 p)
{
    vec2 i = floor(p);
    vec2 f = fract(p);

    // Smooth interpolation (quintic Hermite)
    f = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);

    // Four corners
    float a = hash(i);
    float b = hash(i + vec2(1.0, 0.0));
    float c = hash(i + vec2(0.0, 1.0));
    float d = hash(i + vec2(1.0, 1.0));

    // Bilinear interpolation
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// Fractal Brownian Motion
float fbm(vec2 p, int octaves)
{
    float value = 0.0;
    float amplitude = 0.5;
    float frequency = 1.0;

    for (int i = 0; i < octaves; i++) {
        value += amplitude * noise(p * frequency);
        amplitude *= 0.5;
        frequency *= 2.0;
    }
    return value;
}

void main()
{
    vec2 uv = texCoord * 4.0;

    // Animated fBm for cloud-like pattern
    float n = fbm(uv + vec2(time * 0.1, time * 0.15), 6);

    // Turbulence (absolute value of noise)
    float turb = fbm(abs(uv - 2.0) + time * 0.2, 4);

    // Create fire/cloud colors
    vec3 cloudColor = mix(vec3(0.1, 0.2, 0.4), vec3(1.0, 1.0, 1.0), n);
    vec3 fireColor = mix(vec3(0.5, 0.0, 0.0), vec3(1.0, 0.8, 0.1), turb);

    FragColor = vec4(mix(cloudColor, fireColor, 0.5), 1.0);
}

// Post-processing: Sobel edge detection
#version 330 core

in vec2 texCoord;
uniform sampler2D screenTexture;
uniform vec2 texelSize;  // vec2(1.0/width, 1.0/height)

out vec4 FragColor;

void main()
{
    // Sample neighboring pixels
    vec4 n[9];
    n[0] = texture(screenTexture, texCoord + texelSize * vec2(-1, -1));
    n[1] = texture(screenTexture, texCoord + texelSize * vec2( 0, -1));
    n[2] = texture(screenTexture, texCoord + texelSize * vec2( 1, -1));
    n[3] = texture(screenTexture, texCoord + texelSize * vec2(-1,  0));
    n[4] = texture(screenTexture, texCoord + texelSize * vec2( 0,  0));
    n[5] = texture(screenTexture, texCoord + texelSize * vec2( 1,  0));
    n[6] = texture(screenTexture, texCoord + texelSize * vec2(-1,  1));
    n[7] = texture(screenTexture, texCoord + texelSize * vec2( 0,  1));
    n[8] = texture(screenTexture, texCoord + texelSize * vec2( 1,  1));

    // Sobel kernels for horizontal and vertical edges
    vec4 sobelEdgeH = n[2] + (2.0 * n[5]) + n[8] - (n[0] + (2.0 * n[3]) + n[6]);
    vec4 sobelEdgeV = n[0] + (2.0 * n[1]) + n[2] - (n[6] + (2.0 * n[7]) + n[8]);

    vec4 sobel = sqrt(sobelEdgeH * sobelEdgeH + sobelEdgeV * sobelEdgeV);

    // Show edges in green on black background
    float edgeIntensity = length(sobel.rgb);
    FragColor = vec4(0.0, edgeIntensity, 0.0, 1.0);
}

// PBR Cook-Torrance BRDF implementation
#version 330 core

in vec3 worldPos;
in vec3 worldNormal;
in vec2 texCoord;

uniform vec3 camPos;
uniform vec3 lightPos;
uniform vec3 lightColor;
uniform float lightIntensity;

// Material parameters from textures
uniform sampler2D albedoMap;
uniform sampler2D normalMap;
uniform sampler2D metallicMap;
uniform sampler2D roughnessMap;
uniform sampler2D aoMap;

out vec4 FragColor;

const float PI = 3.14159265359;

// Trowbridge-Reitz GGX Normal Distribution Function
float DistributionGGX(vec3 N, vec3 H, float roughness)
{
    float a = roughness * roughness;
    float a2 = a * a;
    float NdotH = max(dot(N, H), 0.0);
    float NdotH2 = NdotH * NdotH;

    float denom = (NdotH2 * (a2 - 1.0) + 1.0);
    denom = PI * denom * denom;

    return a2 / denom;
}

// Schlick-GGX Geometry Function
float GeometrySchlickGGX(float NdotV, float roughness)
{
    float r = (roughness + 1.0);
    float k = (r * r) / 8.0;

    return NdotV / (NdotV * (1.0 - k) + k);
}

float GeometrySmith(vec3 N, vec3 V, vec3 L, float roughness)
{
    float NdotV = max(dot(N, V), 0.0);
    float NdotL = max(dot(N, L), 0.0);
    float ggx1 = GeometrySchlickGGX(NdotV, roughness);
    float ggx2 = GeometrySchlickGGX(NdotL, roughness);

    return ggx1 * ggx2;
}

// Fresnel-Schlick approximation
vec3 FresnelSchlick(float cosTheta, vec3 F0)
{
    return F0 + (1.0 - F0) * pow(1.0 - cosTheta, 5.0);
}

void main()
{
    // Sample material properties
    vec3 albedo = pow(texture(albedoMap, texCoord).rgb, vec3(2.2)); // Linearize
    float metallic = texture(metallicMap, texCoord).r;
    float roughness = texture(roughnessMap, texCoord).r;
    float ao = texture(aoMap, texCoord).r;

    vec3 N = normalize(worldNormal);
    vec3 V = normalize(camPos - worldPos);
    vec3 L = normalize(lightPos - worldPos);
    vec3 H = normalize(V + L);

    // Distance attenuation
    float dist = length(lightPos - worldPos);
    float attenuation = lightIntensity / (dist * dist);
    vec3 radiance = lightColor * attenuation;

    // Fresnel reflectance at normal incidence
    vec3 F0 = vec3(0.04);  // Dielectric base reflectance
    F0 = mix(F0, albedo, metallic);  // Metals use albedo as F0

    // Cook-Torrance BRDF
    float NDF = DistributionGGX(N, H, roughness);
    float G = GeometrySmith(N, V, L, roughness);
    vec3 F = FresnelSchlick(max(dot(H, V), 0.0), F0);

    vec3 kS = F;  // Specular reflection ratio
    vec3 kD = vec3(1.0) - kS;
    kD *= 1.0 - metallic;  // Metals have no diffuse

    vec3 numerator = NDF * G * F;
    float denominator = 4.0 * max(dot(N, V), 0.0) * max(dot(N, L), 0.0) + 0.0001;
    vec3 specular = numerator / denominator;

    // Lambertian diffuse
    float NdotL = max(dot(N, L), 0.0);
    vec3 diffuse = kD * albedo / PI;

    vec3 Lo = (diffuse + specular) * radiance * NdotL;

    // Ambient with AO
    vec3 ambient = vec3(0.03) * albedo * ao;
    vec3 color = ambient + Lo;

    // HDR tone mapping and gamma correction
    color = color / (color + vec3(1.0));  // Reinhard tone mapping
    color = pow(color, vec3(1.0 / 2.2));   // Gamma correction

    FragColor = vec4(color, 1.0);
}

