// Shadow mapping (second pass) — fragment shader
#version 330 core

in vec3 worldPos;
in vec3 worldNormal;
in vec4 fragPosLightSpace;  // Position in light's clip space

uniform sampler2D shadowMap;
uniform vec3 lightPos;
uniform vec3 viewPos;

out vec4 FragColor;

float ShadowCalculation(vec4 fragPosLightSpace, vec3 normal, vec3 lightDir)
{
    // Perspective divide to get NDC [-1, 1]
    vec3 projCoords = fragPosLightSpace.xyz / fragPosLightSpace.w;

    // Transform to [0, 1] range for texture sampling
    projCoords = projCoords * 0.5 + 0.5;

    // Outside shadow map = not in shadow
    if (projCoords.z > 1.0) return 0.0;

    // Current depth from light's perspective
    float currentDepth = projCoords.z;

    // Bias to prevent shadow acne (based on surface angle to light)
    float bias = max(0.05 * (1.0 - dot(normal, lightDir)), 0.005);

    // PCF: sample surrounding texels for soft shadows
    float shadow = 0.0;
    vec2 texelSize = 1.0 / textureSize(shadowMap, 0);
    for (int x = -1; x <= 1; ++x) {
        for (int y = -1; y <= 1; ++y) {
            float pcfDepth = texture(shadowMap, projCoords.xy + vec2(x, y) * texelSize).r;
            shadow += currentDepth - bias > pcfDepth ? 1.0 : 0.0;
        }
    }
    shadow /= 9.0;  // Average 3x3 samples

    return shadow;
}

void main()
{
    vec3 color = vec3(0.8);
    vec3 normal = normalize(worldNormal);
    vec3 lightDir = normalize(lightPos - worldPos);

    // Diffuse lighting
    float diff = max(dot(normal, lightDir), 0.0);
    vec3 diffuse = diff * vec3(1.0);

    // Ambient
    vec3 ambient = 0.15 * vec3(1.0);

    // Shadow
    float shadow = ShadowCalculation(fragPosLightSpace, normal, lightDir);
    vec3 lighting = ambient + (1.0 - shadow) * diffuse;

    FragColor = vec4(lighting * color, 1.0);
}

