    float dist = length(lightPos - fragPos);

    // Light volume attenuation
    float attenuation = pow(clamp(1.0 - pow(dist / lightRadius, 4.0), 0.0, 1.0), 2.0) 
                        / (dist * dist + 1.0);

    // Simple Lambert for demonstration
    float NdotL = max(dot(N, L), 0.0);
    vec3 radiance = lightColor * attenuation * NdotL;

