// SSAO fragment shader
#version 330 core

in vec2 texCoord;

uniform sampler2D gPosition;
uniform sampler2D gNormal;
uniform sampler2D noiseTexture;

uniform vec3 samples[64];  // Precomputed sample kernel
uniform mat4 projection;
uniform vec2 screenSize;
uniform float radius;
uniform float bias;

out float FragColor;

void main()
{
    vec3 fragPos = texture(gPosition, texCoord).xyz;
    vec3 normal = normalize(texture(gNormal, texCoord).xyz);

    // Random rotation vector from noise texture
    vec2 noiseScale = screenSize / 4.0;
    vec3 randomVec = normalize(texture(noiseTexture, texCoord * noiseScale).xyz);

    // Create TBN matrix
    vec3 tangent = normalize(randomVec - normal * dot(randomVec, normal));
    vec3 bitangent = cross(normal, tangent);
    mat3 TBN = mat3(tangent, bitangent, normal);

    float occlusion = 0.0;
    for (int i = 0; i < 64; i++) {
        // Sample position in view space
        vec3 samplePos = TBN * samples[i];
        samplePos = fragPos + samplePos * radius;

        // Project to screen space
        vec4 offset = vec4(samplePos, 1.0);
        offset = projection * offset;
        offset.xyz = offset.xyz / offset.w * 0.5 + 0.5;

        // Sample depth at this position
        float sampleDepth = texture(gPosition, offset.xy).z;

        // Range check and accumulate
        float rangeCheck = smoothstep(0.0, 1.0, radius / abs(fragPos.z - sampleDepth));
        occlusion += (sampleDepth >= samplePos.z + bias ? 1.0 : 0.0) * rangeCheck;
    }

    FragColor = 1.0 - (occlusion / 64.0);
}

// Screen-Space Reflections (SSR) — simplified ray march
#version 330 core

in vec2 texCoord;

uniform sampler2D colorBuffer;
uniform sampler2D gPosition;
uniform sampler2D gNormal;
uniform mat4 view;
uniform mat4 projection;

out vec4 FragColor;

vec3 SSRTrace(vec3 pos, vec3 reflDir)
{
    vec3 rayPos = pos;
    vec3 step = reflDir * 0.05;  // Step size

    for (int i = 0; i < 50; i++) {
        rayPos += step;

        // Project to screen space
        vec4 clipPos = projection * vec4(rayPos, 1.0);
        vec3 ndc = clipPos.xyz / clipPos.w;
        vec2 uv = ndc.xy * 0.5 + 0.5;

        // Out of bounds
        if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0)
            return vec3(0.0);

        // Sample depth at this screen position
        float sceneDepth = texture(gPosition, uv).z;

        // Intersection found
        if (rayPos.z > sceneDepth) {
            return texture(colorBuffer, uv).rgb;
        }
    }
    return vec3(0.0);  // No hit
}

void main()
{
    vec3 pos = texture(gPosition, texCoord).xyz;
    vec3 normal = normalize(texture(gNormal, texCoord).xyz);
    vec3 viewDir = normalize(-pos);  // View space camera is at origin

    vec3 reflDir = reflect(-viewDir, normal);
    vec3 reflection = SSRTrace(pos, reflDir);

    vec3 baseColor = texture(colorBuffer, texCoord).rgb;
    float reflectivity = 0.3;

    FragColor = vec4(mix(baseColor, reflection, reflectivity), 1.0);
}

// PBR with Image-Based Lighting
#version 330 core

in vec3 worldPos;
in vec3 worldNormal;

uniform vec3 camPos;
uniform samplerCube irradianceMap;
uniform samplerCube prefilteredMap;
uniform sampler2D brdfLUT;
uniform sampler2D albedoMap;
uniform sampler2D metallicRoughnessMap;

out vec4 FragColor;

const float MAX_REFLECTION_LOD = 4.0;

vec3 FresnelSchlickRoughness(float cosTheta, vec3 F0, float roughness)
{
    return F0 + (max(vec3(1.0 - roughness), F0) - F0) * pow(1.0 - cosTheta, 5.0);
}

void main()
{
    vec3 albedo = texture(albedoMap, vec2(0.5)).rgb;  // Simplified
    float metallic = texture(metallicRoughnessMap, vec2(0.5)).r;
    float roughness = texture(metallicRoughnessMap, vec2(0.5)).g;

    vec3 N = normalize(worldNormal);
    vec3 V = normalize(camPos - worldPos);
    float NdotV = max(dot(N, V), 0.0);

    vec3 F0 = vec3(0.04);
    F0 = mix(F0, albedo, metallic);

    // Diffuse IBL: sample irradiance with normal
    vec3 kS = FresnelSchlickRoughness(NdotV, F0, roughness);
    vec3 kD = 1.0 - kS;
    kD *= 1.0 - metallic;
    vec3 irradiance = texture(irradianceMap, N).rgb;
    vec3 diffuse = irradiance * albedo;

    // Specular IBL: sample prefiltered reflection
    vec3 R = reflect(-V, N);
    vec3 prefilteredColor = textureLod(prefilteredMap, R, roughness * MAX_REFLECTION_LOD).rgb;
    vec2 brdf = texture(brdfLUT, vec2(NdotV, roughness)).rg;
    vec3 specular = prefilteredColor * (kS * brdf.x + brdf.y);

    vec3 ambient = kD * diffuse + specular;

    FragColor = vec4(ambient, 1.0);
}

// Equirectangular to cube map conversion shader
