    vec3 color = texture(equirectangularMap, uv).rgb;
    FragColor = vec4(color, 1.0);
}

// Compute shader: Parallel array sum reduction
#version 430 core

layout(local_size_x = 256, local_size_y = 1, local_size_z = 1) in;

layout(std430, binding = 0) readonly buffer InputBuffer {
    float data[];
} inputBuffer;

layout(std430, binding = 1) writeonly buffer OutputBuffer {
    float data[];
} outputBuffer;

shared float sharedData[256];

uniform uint n;

void main()
{
    uint tid = gl_LocalInvocationID.x;
    uint gid = gl_GlobalInvocationID.x;

    // Load data into shared memory
    sharedData[tid] = (gid < n) ? inputBuffer.data[gid] : 0.0;
    barrier();  // Ensure all loads complete

    // Parallel reduction in shared memory
    for (uint stride = 128; stride > 0; stride >>= 1) {
        if (tid < stride) {
            sharedData[tid] += sharedData[tid + stride];
        }
        barrier();  // Synchronize before next iteration
    }

    // Write result
    if (tid == 0) {
        outputBuffer.data[gl_WorkGroupID.x] = sharedData[0];
    }
}

// Compute shader: Image processing (Gaussian blur)
#version 430 core

layout(local_size_x = 16, local_size_y = 16) in;

layout(rgba8, binding = 0) readonly uniform image2D inputImage;
layout(rgba8, binding = 1) writeonly uniform image2D outputImage;

uniform int blurRadius;

void main()
{
    ivec2 coord = ivec2(gl_GlobalInvocationID.xy);
    ivec2 imgSize = imageSize(inputImage);

    if (coord.x >= imgSize.x || coord.y >= imgSize.y) return;

    vec4 sum = vec4(0.0);
    int count = 0;

    for (int x = -blurRadius; x <= blurRadius; x++) {
        for (int y = -blurRadius; y <= blurRadius; y++) {
            ivec2 sampleCoord = coord + ivec2(x, y);
            sampleCoord = clamp(sampleCoord, ivec2(0), imgSize - ivec2(1));
            sum += imageLoad(inputImage, sampleCoord);
            count++;
        }
    }

    imageStore(outputImage, coord, sum / float(count));
}

// Tessellation Control Shader (TCS)
