    vec3 p0 = gl_TessCoord.x * tcsWorldPos[0];
    vec3 p1 = gl_TessCoord.y * tcsWorldPos[1];
    vec3 p2 = gl_TessCoord.z * tcsWorldPos[2];
    worldPos = p0 + p1 + p2;

    vec2 uv0 = gl_TessCoord.x * tcsTexCoord[0];
    vec2 uv1 = gl_TessCoord.y * tcsTexCoord[1];
    vec2 uv2 = gl_TessCoord.z * tcsTexCoord[2];
    texCoord = uv0 + uv1 + uv2;

    // Displace along interpolated normal
    float height = texture(displacementMap, texCoord).r;
    vec3 normal = normalize(cross(
        tcsWorldPos[1] - tcsWorldPos[0],
