    worldNormal = normal;  // Ideally recalculate from displaced geometry
    gl_Position = mvp * vec4(worldPos, 1.0);
}

// Ray marching with SDFs — complete scene in one fragment shader
#version 330 core

in vec2 texCoord;
uniform vec2 resolution;
uniform float time;

out vec4 FragColor;

// SDF primitives
float sdSphere(vec3 p, float r) {
    return length(p) - r;
}

float sdBox(vec3 p, vec3 b) {
    vec3 d = abs(p) - b;
    return min(max(d.x, max(d.y, d.z)), 0.0) + length(max(d, 0.0));
}

float sdTorus(vec3 p, vec2 t) {
    vec2 q = vec2(length(p.xz) - t.x, p.y);
    return length(q) - t.y;
}

// Smooth union for organic blending
float smin(float a, float b, float k) {
    float h = max(k - abs(a - b), 0.0) / k;
    return min(a, b) - h * h * k * 0.25;
}

// Scene SDF
float map(vec3 p) {
    // Animated sphere
    vec3 spherePos = vec3(sin(time) * 2.0, 0.0, cos(time) * 2.0);
    float sphere = sdSphere(p - spherePos, 0.8);

    // Ground plane (infinite box)
    float ground = sdBox(p - vec3(0.0, -2.0, 0.0), vec3(100.0, 0.1, 100.0));

    // Central torus
    float torus = sdTorus(p, vec2(1.5, 0.4));

    // Combine with smooth blending
    return smin(smin(sphere, ground, 0.5), torus, 0.3);
}

// Calculate normal from SDF gradient
vec3 calcNormal(vec3 p) {
    float eps = 0.001;
    return normalize(vec3(
        map(p + vec3(eps, 0, 0)) - map(p - vec3(eps, 0, 0)),
        map(p + vec3(0, eps, 0)) - map(p - vec3(0, eps, 0)),
        map(p + vec3(0, 0, eps)) - map(p - vec3(0, 0, eps))
    ));
}

void main()
{
    // Normalized pixel coordinates (-1 to 1)
    vec2 uv = (texCoord - 0.5) * 2.0;
    uv.x *= resolution.x / resolution.y;

    // Camera setup
    vec3 ro = vec3(0.0, 1.0, 5.0);  // Ray origin
    vec3 rd = normalize(vec3(uv, -1.5));  // Ray direction

    // Rotate camera around scene
    float angle = time * 0.3;
    mat2 rot = mat2(cos(angle), -sin(angle), sin(angle), cos(angle));
    ro.xz = rot * ro.xz;
    rd.xz = rot * rd.xz;

    // Sphere tracing
    float t = 0.0;
    float hit = 0.0;
    for (int i = 0; i < 100; i++) {
        vec3 p = ro + rd * t;
        float d = map(p);
        if (d < 0.001) { hit = 1.0; break; }
        if (t > 50.0) break;
        t += d;
    }

    vec3 color = vec3(0.05, 0.05, 0.1);  // Background

    if (hit > 0.5) {
        vec3 p = ro + rd * t;
        vec3 normal = calcNormal(p);

        // Lighting
        vec3 lightDir = normalize(vec3(1.0, 2.0, 1.0));
        float diff = max(dot(normal, lightDir), 0.0);

        vec3 viewDir = -rd;
        vec3 halfDir = normalize(lightDir + viewDir);
        float spec = pow(max(dot(normal, halfDir), 0.0), 64.0);

        // Color based on position for visual interest
        vec3 matColor = 0.5 + 0.5 * cos(vec3(0.0, 2.0, 4.0) + p.x * 0.5);

        color = matColor * (0.2 + diff) + vec3(1.0) * spec * 0.5;

        // Fog
        color = mix(color, vec3(0.05, 0.05, 0.1), 1.0 - exp(-t * 0.05));
    }

    FragColor = vec4(color, 1.0);
}

// Volumetric light shafts (god rays) in screen space
