    return normalize(vec3(
        map(p+vec3(e,0,0)) - map(p-vec3(e,0,0)),
        map(p+vec3(0,e,0)) - map(p-vec3(0,e,0)),
        map(p+vec3(0,0,e)) - map(p-vec3(0,0,e))
    ));
}

void main()
{
    vec2 uv = (texCoord - 0.5) * 2.0;
    uv.x *= resolution.x / resolution.y;

    // Camera from ray marching (Part 18)
    vec3 ro = vec3(0, 1, 4);
    vec3 rd = normalize(vec3(uv, -2));

    float t = 0.0, hit = 0.0;
    for (int i = 0; i < 80; i++) {
        float d = map(ro + rd * t);
        if (d < 0.001) { hit = 1.0; break; }
        t += d;
        if (t > 30.0) break;
    }

    vec3 col = vec3(0.02, 0.02, 0.05);
    if (hit > 0.5) {
        vec3 p = ro + rd * t;
        vec3 n = calcNormal(p);
        vec3 l = normalize(vec3(1, 2, 1));

        // PBR-style lighting from Part 11
        float diff = max(dot(n, l), 0.0);
        vec3 h = normalize(l - rd);
        float spec = pow(max(dot(n, h), 0.0), 128.0);

        // Procedural color from Part 10
        vec3 mat = 0.5 + 0.5 * cos(vec3(0, 2, 4) + p.y * 0.5 + time);
        col = mat * diff + vec3(1.0) * spec;

        // Fog from atmospheric scattering (Part 19)
        col = mix(vec3(0.02, 0.02, 0.05), col, exp(-t * 0.1));
    }

    // Tone mapping from PBR (Part 11)
    col = col / (col + vec3(1.0));
    col = pow(col, vec3(1.0/2.2));

    FragColor = vec4(col, 1.0);
}
